"""Generate a mocked browser fixture; PASS is written to body data-test-result."""
from pathlib import Path
import sys
root=Path(__file__).resolve().parents[2]
mock="<script>window.commands=[];window.fetch=async function(url,opts){if(opts&&opts.body)commands.push([url,opts.body]);return {ok:true,status:200,json:async()=>url.includes('/status')?{machine:'master',bluetooth_keyboard:{state:'connected',remembered:true,capturing:false,pin:''},keyboard_mappings:[]}: {},text:async()=>''};};</script>"
test="<script>setTimeout(async()=>{try{for(const machine of ['master','beeb']){\n const base={machine,bluetooth_keyboard:{state:'connected',remembered:true,pin:'',capturing:false},keyboard_mappings:[]};show(base);\n await keyboardMappingStart();if(!mappingActive)throw Error('capture start');show({...base,bluetooth_keyboard:{...base.bluetooth_keyboard,capturing:true,captured_usage:4}});\n if(mappingUsage!==4)throw Error('capture usage');const key=[...$('kbwrap').querySelectorAll('[data-code]')].find(k=>/^\\d+$/.test(k.dataset.code)&&Number(k.dataset.code)<128);const target=key.dataset.code;\n const before=commands.length;key.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,cancelable:true}));await new Promise(r=>setTimeout(r,10));\n if(!commands.slice(before).some(x=>x[1]===`keyboard map 4 ${target}`))throw Error(machine+' map save');\n if(commands.slice(before).some(x=>x[0].includes('/keys')))throw Error('key leaked');\n show({...base,keyboard_mappings:[[4,Number(target)]]});$('keyboardMappings').value='4';await keyboardMappingDelete();if(commands.at(-1)[1]!=='keyboard unmap 4')throw Error('delete');\n await keyboardMappingStart();await keyboardMappingCancel();if(mappingActive)throw Error('cancel');}\n document.body.dataset.testResult='PASS';}catch(e){document.body.dataset.testResult='FAIL '+e.message;}},500);</script>"
html=(root/"src/common/api/web/index.html").read_text().replace("<script>",mock+"<script>",1).replace("</body>",test+"</body>")
Path(sys.argv[1]).write_text(html)
